// PROTOTYPE, never merged: PostHog/michaelr-context#419. How you enter Email & Messaging, and what its sidebar holds.
import { MakeLogicType, actions, kea, path, reducers } from 'kea'
import { router, urlToAction } from 'kea-router'

export const MESSAGING_NAV_VARIANTS = ['A', 'B', 'C'] as const
export type MessagingNavVariant = (typeof MESSAGING_NAV_VARIANTS)[number]

export function isMessagingNavVariant(value: unknown): value is MessagingNavVariant {
    return typeof value === 'string' && (MESSAGING_NAV_VARIANTS as readonly string[]).includes(value)
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface messagingNavPrototypeLogicValues {
    variant: MessagingNavVariant
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface messagingNavPrototypeLogicActions {
    setVariant: (variant: MessagingNavVariant) => {
        variant: MessagingNavVariant
    }
}

export type messagingNavPrototypeLogicType = MakeLogicType<
    messagingNavPrototypeLogicValues,
    messagingNavPrototypeLogicActions
>

export const messagingNavPrototypeLogic = kea<messagingNavPrototypeLogicType>([
    path(['layout', 'today', 'messagingNavPrototype', 'messagingNavPrototypeLogic']),
    actions({
        setVariant: (variant: MessagingNavVariant) => ({ variant }),
    }),
    reducers({
        variant: [
            'A' as MessagingNavVariant,
            { persist: true, prefix: 'prototype-419' },
            { setVariant: (_, { variant }) => variant },
        ],
    }),
    urlToAction(({ actions, values }) => ({
        '*': (_, searchParams) => {
            const fromUrl = searchParams.variant
            if (isMessagingNavVariant(fromUrl) && fromUrl !== values.variant) {
                actions.setVariant(fromUrl)
            }
        },
    })),
])

/** Switches the variant and keeps it in the URL, so a shared link opens the same variant. */
export function switchMessagingNavVariant(variant: MessagingNavVariant): void {
    messagingNavPrototypeLogic.actions.setVariant(variant)
    router.actions.replace(
        router.values.location.pathname,
        { ...router.values.searchParams, variant },
        router.values.hashParams
    )
}

/** The variant while the prototype logic is mounted, else null, so the shell runs unchanged outside the prototype. */
export function currentMessagingNavVariant(): MessagingNavVariant | null {
    return messagingNavPrototypeLogic.findMounted()?.values.variant ?? null
}
